export const SchedulePathDto = zod
    .object({
        kind: zod
            .enum(['instant', 'standard'])
            .describe(
                'instant = atomic same-tx, liquidity\/limit-bounded; standard = windowed \/ off-chain settled',
            ),
        cadence: zod
            .enum(['continuous', 'daily_cutoff', 'periodic', 'scheduled'])
            .describe('How the path recurs'),
        status: zod
            .enum(['open', 'closed', 'settling'])
            .describe('Live status, refreshed by cron \/ on-chain read'),
        businessDaysOnly: zod
            .boolean()
            .optional()
            .describe('false\/omitted = 24\/7\/365 (instant DeFi paths); true = market days only'),
        cutoffTime: zod
            .string()
            .optional()
            .describe('For daily_cutoff: local cutoff time orders must be in by, e.g. \"16:00\"'),
        currentWindow: zod
            .object({
                opensAt: zod.string().describe('Window open time (ISO 8601)'),
                closesAt: zod
                    .string()
                    .describe(
                        'Window close \/ cutoff time (ISO 8601); orders after this roll to nextWindow',
                    ),
                source: zod
                    .enum(['onchain', 'api', 'config'])
                    .optional()
                    .describe(
                        'Provenance of this window (on-chain read, issuer API, or hardcoded config)',
                    ),
            })
            .nullish()
            .describe('The window the user is acting into right now (null when continuous)'),
        nextWindow: zod
            .object({
                opensAt: zod.string().describe('Window open time (ISO 8601)'),
                closesAt: zod
                    .string()
                    .describe(
                        'Window close \/ cutoff time (ISO 8601); orders after this roll to nextWindow',
                    ),
                source: zod
                    .enum(['onchain', 'api', 'config'])
                    .optional()
                    .describe(
                        'Provenance of this window (on-chain read, issuer API, or hardcoded config)',
                    ),
            })
            .nullish()
            .describe('The next window after the current one closes; what a UI counts down to'),
        settlement: zod
            .object({
                type: zod
                    .enum(['atomic', 'next_business_day', 'cohort', 'cooldown'])
                    .describe(
                        'How the order settles: atomic (same tx), next_business_day, cohort (batched off-chain), or cooldown (fixed delay)',
                    ),
                marketDays: zod
                    .number()
                    .optional()
                    .describe('Settlement horizon in market days (T+N) when applicable'),
                estimatedDuration: zod
                    .object({
                        seconds: zod.number().describe('Duration in seconds'),
                    })
                    .optional()
                    .describe('Best estimate of full settlement when not atomic'),
                estimatedSettlementAt: zod
                    .string()
                    .optional()
                    .describe('Concrete settlement date when known (ISO 8601, cohort\/scheduled)'),
                claimRequired: zod
                    .boolean()
                    .optional()
                    .describe(
                        'User must submit a separate on-chain claim to receive settled funds (ERC-7540)',
                    ),
                instantPortion: zod
                    .number()
                    .optional()
                    .describe(
                        'Split delivery: fraction (0-1) delivered instantly; the rest is deferred',
                    ),
                deferredDeliveryAt: zod
                    .string()
                    .optional()
                    .describe('Concrete date the deferred portion is delivered (ISO 8601)'),
            })
            .describe('When the order is actually processed'),
        accrual: zod
            .object({
                startsAt: zod
                    .enum(['immediate', 'next_business_day', 'on_cycle_start', 'on_settlement'])
                    .describe(
                        'When earning starts (subscription) \/ earn-through boundary (redemption): immediate, next_business_day, on_cycle_start, or on_settlement',
                    ),
                startsAtDate: zod
                    .string()
                    .optional()
                    .describe('Concrete accrual start date when known (ISO 8601, cron-filled)'),
                minimumHold: zod
                    .object({
                        seconds: zod.number().describe('Duration in seconds'),
                    })
                    .optional()
                    .describe('Minimum hold before redemption is allowed'),
            })
            .describe('When earning starts\/stops relative to the order'),
        limits: zod
            .object({
                individualPer24h: zod
                    .string()
                    .optional()
                    .describe('Per-investor cap per rolling 24h'),
                globalPer24h: zod.string().optional().describe('Protocol-wide cap per rolling 24h'),
                maxFractionOfNav: zod
                    .number()
                    .optional()
                    .describe('On-demand pool cap as a fraction of NAV (0-1)'),
                liquidityBounded: zod
                    .boolean()
                    .optional()
                    .describe(
                        'Path depends on an on-chain liquidity buffer; live depth lives in state.liquidityState',
                    ),
                minimumAmount: zod
                    .string()
                    .optional()
                    .describe('Per-path minimum when it differs from mechanics.entryLimits'),
            })
            .optional()
            .describe('Caps that gate an instant path or an on-demand liquidity pool'),
    })
    .meta({ id: 'SchedulePathDto' });

